type S struct{ n int }
type Opt func(*S)

func WithN(n int) Opt { return func(s *S) { s.n = n } }

func New(opts ...Opt) *S {
	s := &S{n: 1}
	for _, o := range opts {
		o(s)
	}
	return s
}

func main() {
	fmt.Println(New().n, New(WithN(5), WithN(7)).n)
}

